def evaluate(current_reputation, observation, my_history, round_num):
    # Use a simple moving average of the most recent 5 actions (including current).
    # Score: cooperate -> +0.8, defect -> -1.2 (slightly harsher on defection)
    recent_vals = []
    # Current observation
    recent_vals.append(0.8 if observation['action'] == 'cooperate' else -1.2)
    # Past actions from my_history (reverse chronological, take up to 4 more)
    for entry in reversed(my_history):
        if len(recent_vals) >= 5:
            break
        partner_val = 0.8 if entry.get('partner_action', 'defect') == 'cooperate' else -1.2
        recent_vals.append(partner_val)
    # If we have fewer than 5 values, pad with current_reputation? No, just average.
    avg = sum(recent_vals) / len(recent_vals) if recent_vals else 0.0
    return max(-1.0, min(1.0, avg))

def decide(recipient_reputation, round_num, my_history):
    # Threshold starts low for early trust-building, then increases.
    if round_num <= 4:
        base_threshold = 0.3
    else:
        base_threshold = 0.5

    # Adjust based on own cooperation rate (from my_history)
    own_coop = sum(1 for entry in my_history if entry.get('own_action', 'cooperate') == 'cooperate')
    own_total = len(my_history)
    if own_total > 0:
        coop_rate = own_coop / own_total
        # If I've cooperated a lot, raise threshold to avoid exploitation.
        # If I've defected a lot, lower threshold to encourage cooperation.
        if coop_rate > 0.7:
            adjustment = +0.2
        elif coop_rate < 0.3:
            adjustment = -0.2
        else:
            adjustment = 0.0
    else:
        adjustment = 0.0

    threshold = base_threshold + adjustment
    return recipient_reputation > threshold
